// ── Anvil receipts: publication-bound tamper-evident verdict ──────
// Subcontract `anvil_receipts` v1.0 (manifest.json → subcontracts).
// Schema branch: schema/core-event.schema.json, type const 'anvil_receipt'.
// That branch sets additionalProperties: true, so the wire may legitimately
// carry fields not listed here; the ledger hashes the whole body and
// interprets only what is declared.
| {
    type: 'anvil_receipt';
    // Required by the schema's `required` array (11 fields + type).
    receipt_id: string;
    event_id: string;
    origin: 'core/anvil';
    contract_version: string;
    session_id: string;
    run_id: string;
    task_id: string;
    sequence: number;
    artifact_digest: string;
    gate_closure_digest: string;
    receipt_body_digest: string;
    // Declared in `properties`, absent from `required`.
    artifact_scope?: string;
    checks_passed?: number;
    checks_total?: number;
    cost_microcents?: number;
    coverage?: string;
    digest_algorithm?: 'sha256';
    engine_version?: string;
    issued_at_unix_ms?: number;
    iterations?: number;
    priced?: boolean;
    stamp?: string;
    supersedes_receipt_id?: string;
    /** Schema pins this to the const 'verified'. Any other value is a
     *  schema violation, which is how `adversarial/anvil/altered-body.jsonl`
     *  (terminal_state: 'tampered') is caught - measured, not assumed. */
    terminal_state?: 'verified';
    valve_fires?: number;
    /** NOT in the schema's `properties` block. It exists in exactly one file
     *  in the whole bundle - adversarial/anvil/unknown-critical-extension.jsonl
     *  - and validates only because additionalProperties is true. A non-empty
     *  value names an extension the receipt REQUIRES its reader to implement.
     *  This host implements none, so any entry means reject. */
    required_extensions?: string[];
  }

| {
    type: 'anvil_receipt_invalidated';
    // Required by the schema's `required` array (12 fields + type).
    receipt_id: string;
    event_id: string;
    origin: 'core/anvil';
    contract_version: string;
    session_id: string;
    run_id: string;
    task_id: string;
    sequence: number;
    reason: 'artifact_mutated' | 'gate_revoked' | 'superseded';
    prior_artifact_digest: string;
    invalidation_body_digest: string;
    // Declared in `properties`, absent from `required`.
    issued_at_unix_ms?: number;
    observed_artifact_digest?: string;
  }
